var doc = Document;
// Goal: a wall schedule with Type, Length and Area columns, sorted by length, with the rows read
// back so the caller can report them.

Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) { if (level == null || l.Elevation < level.Elevation) level = l; }

return Connector.WithTransaction(doc, () => {
  // 1. Two walls of different length so the schedule has rows to sort (setup only).
  Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 0, 0), new Autodesk.Revit.DB.XYZ(30, 0, 0)), level.Id, false);
  Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 10, 0), new Autodesk.Revit.DB.XYZ(12, 10, 0)), level.Id, false);
  doc.Regenerate();

  // 2. Create the schedule for a category. The category goes in as an ElementId of the BuiltInCategory.
  var categoryId = new Autodesk.Revit.DB.ElementId(Autodesk.Revit.DB.BuiltInCategory.OST_Walls);
  var schedule = Autodesk.Revit.DB.ViewSchedule.CreateSchedule(doc, categoryId);
  schedule.Name = "Wall Schedule (how-to)";
  var def = schedule.Definition;

  // 3. Fields are chosen from GetSchedulableFields by PARAMETER ID, not by display name (names are
  //    localised and not unique). BuiltInParameter values cast to long match SchedulableField.ParameterId.
  var wanted = new System.Collections.Generic.List<Autodesk.Revit.DB.BuiltInParameter> {
    Autodesk.Revit.DB.BuiltInParameter.ELEM_TYPE_PARAM,
    Autodesk.Revit.DB.BuiltInParameter.CURVE_ELEM_LENGTH,
    Autodesk.Revit.DB.BuiltInParameter.HOST_AREA_COMPUTED };
  var added = new System.Collections.Generic.Dictionary<long, Autodesk.Revit.DB.ScheduleField>();
  foreach (var bip in wanted) {
    foreach (var sf in def.GetSchedulableFields()) {
      if (sf.ParameterId.Value == (long)bip) { added[(long)bip] = def.AddField(sf); break; }
    }
  }

  // 4. Sort by length, descending. AddSortGroupField takes the ScheduleField's FieldId.
  var lengthField = added[(long)Autodesk.Revit.DB.BuiltInParameter.CURVE_ELEM_LENGTH];
  var sort = new Autodesk.Revit.DB.ScheduleSortGroupField(lengthField.FieldId, Autodesk.Revit.DB.ScheduleSortOrder.Descending);
  def.AddSortGroupField(sort);
  doc.Regenerate();

  // 5. Read the body back: the Body section of GetTableData holds the header row(s) then one row
  //    per element. GetCellText returns the formatted text the user would see.
  var body = schedule.GetTableData().GetSectionData(Autodesk.Revit.DB.SectionType.Body);
  var rows = new System.Collections.Generic.List<string[]>();
  for (int r = body.FirstRowNumber; r <= body.LastRowNumber; r++) {
    var cells = new string[body.NumberOfColumns];
    for (int c = 0; c < body.NumberOfColumns; c++) { cells[c] = schedule.GetCellText(Autodesk.Revit.DB.SectionType.Body, r, c); }
    rows.Add(cells);
  }

  // 6. Verify: the field count and header row match what was asked; row count is header + walls.
  return new { scheduleId = schedule.Id.Value, name = schedule.Name, fieldCount = def.GetFieldCount(), header = rows.Count > 0 ? rows[0] : null, rowCount = rows.Count, rows };
});
